#!/usr/bin/env bash
#
# Build a browsable TYPO3 demo instance for manually testing EXT:imaginator.
#
# Run from the project root with DDEV:
#     ddev composer install
#     ddev exec bash Build/Scripts/setup-demo-instance.sh
#
# Afterwards:
#     Frontend: https://imaginator.ddev.site/
#     Backend:  https://imaginator.ddev.site/typo3/   (admin / Password.1)
#
# The instance itself (config/, .Build/, var/, fileadmin uploads, database) is git-ignored and
# fully regenerated by this script — re-run it any time to get a clean instance.

set -euo pipefail

BASE_URL="https://imaginator.ddev.site/"
ADMIN_USER="admin"
ADMIN_PASS="Password.1"
SITE_CONFIG="config/sites/main/config.yaml"

echo "› resetting the database for a clean install"
mysql -h db -u root -proot -e "DROP DATABASE IF EXISTS db; CREATE DATABASE db CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;" 2>/dev/null

echo "› TYPO3 setup (database + admin user + site)"
.Build/bin/typo3 setup \
    --driver=mysqli --host=db --port=3306 --dbname=db --username=db --password=db \
    --admin-username="${ADMIN_USER}" --admin-user-password="${ADMIN_PASS}" --admin-email=admin@example.com \
    --project-name=Imaginator --create-site="${BASE_URL}" --server-type=other --no-interaction --force

echo "› wiring the demo Site Set into the site configuration"
if ! grep -q 'schliesser/imaginator-demo' "${SITE_CONFIG}"; then
    sed -i 's#^dependencies:#dependencies:\n  - schliesser/imaginator-demo#' "${SITE_CONFIG}"
fi

echo "› neutralising the installer's welcome-page TypoScript (the demo Set renders the page)"
printf '# Page rendering is provided by the schliesser/imaginator-demo Site Set.\n' \
    > config/sites/main/setup.typoscript

echo "› placing the demo images into fileadmin"
mkdir -p .Build/public/fileadmin/demo
cp Build/demo/*.jpg Build/demo/*.png .Build/public/fileadmin/demo/

echo "› finalising extensions and caches"
.Build/bin/typo3 extension:setup
# Publish public assets to _assets/. In this demo the extension IS the root package, so its
# Resources/Public (e.g. the backend aspect-ratios web component) is not auto-published by
# extension:setup the way vendor-installed extensions are; publish it explicitly so v14's
# importmap can resolve EXT:imaginator/Resources/Public/JavaScript/ in the backend.
.Build/bin/typo3 asset:publish
.Build/bin/typo3 cache:flush
# A fresh install can leave a stale empty page in the page cache; clear it directly.
mysql -h db -u db -pdb db -e "TRUNCATE cache_pages;" 2>/dev/null || true

echo "› indexing demo images in FAL (warm-up request)"
curl -sk -o /dev/null "${BASE_URL}" || true

echo "› creating cropped FileReference demo content elements"
mysql -h db -u db -pdb db <<'SQL' || true
SET @hero   = (SELECT uid FROM sys_file WHERE identifier = '/demo/hero.jpg'   LIMIT 1);
SET @banner = (SELECT uid FROM sys_file WHERE identifier = '/demo/banner.jpg' LIMIT 1);
SET @single = (SELECT uid FROM sys_file WHERE identifier = '/demo/single.jpg' LIMIT 1);

INSERT INTO tt_content (pid, sorting, colPos, CType, header, bodytext, assets, aspect_ratio)
VALUES (1, 256, 0, 'textmedia', 'Per-breakpoint: xs 1:1 -> md 4:3 -> lg 16:9 (hero.jpg)', '<p>One CE ratio map drives every media reference. The reference crops the left 40% of a landscape source; each per-breakpoint ratio is fitted inside that crop area (focus-centered). Resize to watch the picture switch.</p>', 1, '{"xs":"1:1","md":"4:3","lg":"16:9"}');
INSERT INTO sys_file_reference (pid, uid_local, uid_foreign, tablenames, fieldname, sorting_foreign, crop)
VALUES (1, @hero, LAST_INSERT_ID(), 'tt_content', 'assets', 1,
  '{"default":{"cropArea":{"x":0,"y":0,"width":0.4,"height":1},"selectedRatio":"NaN","focusArea":{"x":0,"y":0,"width":0,"height":0}}}');

INSERT INTO tt_content (pid, sorting, colPos, CType, header, bodytext, assets, aspect_ratio)
VALUES (1, 512, 0, 'textmedia', 'Per-breakpoint: xs 4:3 -> lg 21:9 (banner.jpg)', '<p>A wide center band; each per-breakpoint ratio is fitted inside it - only the cropped pixels are transferred.</p>', 1, '{"xs":"4:3","lg":"21:9"}');
INSERT INTO sys_file_reference (pid, uid_local, uid_foreign, tablenames, fieldname, sorting_foreign, crop)
VALUES (1, @banner, LAST_INSERT_ID(), 'tt_content', 'assets', 1,
  '{"default":{"cropArea":{"x":0.05,"y":0.35,"width":0.9,"height":0.3},"selectedRatio":"NaN","focusArea":{"x":0,"y":0,"width":0,"height":0}}}');

INSERT INTO tt_content (pid, sorting, colPos, CType, header, bodytext, assets, aspect_ratio)
VALUES (1, 768, 0, 'textmedia', 'Per-breakpoint: xs 1:1 -> sm 3:2 -> lg 4:3 (single.jpg)', '<p>An off-center crop region; each per-breakpoint ratio is fitted inside it, honoured server-side.</p>', 1, '{"xs":"1:1","sm":"3:2","lg":"4:3"}');
INSERT INTO sys_file_reference (pid, uid_local, uid_foreign, tablenames, fieldname, sorting_foreign, crop)
VALUES (1, @single, LAST_INSERT_ID(), 'tt_content', 'assets', 1,
  '{"default":{"cropArea":{"x":0.45,"y":0.3,"width":0.55,"height":0.7},"selectedRatio":"NaN","focusArea":{"x":0,"y":0,"width":0,"height":0}}}');
SQL

.Build/bin/typo3 cache:flush
mysql -h db -u db -pdb db -e "TRUNCATE cache_pages;" 2>/dev/null || true

cat <<EOF

Done.
  Frontend: ${BASE_URL}
  Backend:  ${BASE_URL}typo3/   (user: ${ADMIN_USER}  pass: ${ADMIN_PASS})
EOF
